// Make the agent's inputs safe and predictable before touching the database
const j = $json;

// card: "credit", "debit", or the last 4 digits. Never keep more than 4 digits.
const raw = String(j.card ?? '').toLowerCase();
let card = '';
if (raw.includes('credit')) card = 'credit';
else if (raw.includes('debit')) card = 'debit';
else {
  const digits = raw.replace(/\D/g, '');
  if (digits.length >= 4) card = digits.slice(-4);
}

// delivery: turn the caller's words into "express", "standard", or empty
const dv = String(j.delivery ?? '').toLowerCase();
let delivery = '';
if (/express|fast|quick|urgent|rush|asap|two.?day|2.?day/.test(dv)) delivery = 'express';
else if (/standard|normal|regular|free|slow|usual/.test(dv)) delivery = 'standard';

// confirmed: only an explicit yes counts
const yesWords = ['yes', 'y', 'true', 'confirmed', '1'];
const confirmed = yesWords.includes(String(j.confirmed ?? '').trim().toLowerCase()) ? 'yes' : '';

return {
  json: {
    customer_id: String(j.customer_id ?? '').replace(/\D/g, ''),
    security_answer: String(j.security_answer ?? ''),
    card,
    delivery,
    confirmed,
  },
};

// Turn the result into clear instructions for the agent
const j = $json;
const input = $('Clean inputs').item.json;

if (!j || !j.customer_id) {
  return { json: { result: 'NOT VERIFIED. The customer ID or security answer did not match. Do not take any action. Ask the caller to verify again.' } };
}

const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const all = list(j.all_cards);
const target = list(j.target);
const existing = list(j.existing);
const inserted = list(j.inserted);
const name = k => `${k.type} card ending ${k.last4}`;
const money = n => Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' });

// Count forward a number of business days, skipping Saturdays and Sundays
const addBusinessDays = (start, n) => {
  const d = new Date(start);
  let added = 0;
  while (added < n) {
    d.setDate(d.getDate() + 1);
    const day = d.getDay();
    if (day !== 0 && day !== 6) added++;
  }
  return d;
};
const fmt = d => d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
const arrival = (delivery, from) => delivery === 'express'
  ? `by ${fmt(addBusinessDays(from, 2))}`
  : `between ${fmt(addBusinessDays(from, 5))} and ${fmt(addBusinessDays(from, 7))}`;

const today = new Date();
const eligibleStatuses = ['blocked', 'lost', 'expired'];
let result;

if (inserted.length) {
  // The replacement was ordered
  const r = inserted[0];
  const k = target[0];
  const feeText = Number(r.fee) > 0
    ? `The ${money(r.fee)} express fee has been added to their checking account as a pending charge.`
    : (r.delivery === 'express' ? 'Express delivery is free because the card was blocked for fraud.' : 'Standard delivery is free.');
  result = `DONE. A replacement for the ${name(k)} has been ordered with ${r.delivery} delivery. It should arrive ${arrival(r.delivery, new Date(r.created_at))}. ${feeText} The new card will have a new card number, so the caller should update any subscriptions or saved payments that use the old card. Tell the caller this in two or three short sentences.`;

} else if (existing.length) {
  // A replacement is already on its way
  const r = existing[0];
  const k = target[0];
  const ordered = new Date(r.created_at);
  result = `ALREADY ORDERED. A replacement for the ${name(k)} was already ordered on ${fmt(ordered)} with ${r.delivery} delivery. It should arrive ${arrival(r.delivery, ordered)}. Do not order another one. Tell the caller this.`;

} else if (target.length) {
  const k = target[0];
  if (!eligibleStatuses.includes(k.status)) {
    // The card is still active
    result = `CARD IS STILL ACTIVE. The ${name(k)} is active, so it does not need replacing. If the caller lost it or it was stolen or misused, offer to block it first with block_card, then order the replacement.`;
  } else {
    // The same fee rule as the database: express is free if the card was blocked for fraud
    const expressFee = k.status === 'blocked' ? 0 : 25;
    const expressText = expressFee
      ? `express costs ${money(expressFee)} and arrives ${arrival('express', today)}`
      : `express is free in this case because the card was blocked for fraud, and arrives ${arrival('express', today)}`;

    if (!input.delivery) {
      // Ask which delivery they want
      result = `CHOOSE DELIVERY. The ${name(k)} can be replaced. Ask the caller: standard delivery is free and arrives ${arrival('standard', today)}, or ${expressText}. Which would they like? Then use request_replacement_card again with the delivery they chose.`;
    } else {
      // Delivery chosen, now confirm
      const fee = input.delivery === 'express' ? expressFee : 0;
      const feeText = fee ? `, with a ${money(fee)} fee charged to your checking account` : ', free of charge';
      result = `NOT DONE YET. Ask the caller to confirm: "Just to confirm, you'd like a replacement for your ${name(k)} by ${input.delivery} delivery${feeText}, arriving ${arrival(input.delivery, today)}?" Only if they clearly say yes, use request_replacement_card again with delivery set to ${input.delivery} and confirmed set to yes.`;
    }
  }

} else {
  const cardsText = all.length ? all.map(k => `${name(k)} (${k.status})`).join(', ') : 'none';
  if (input.card) {
    result = `NO MATCHING CARD. No card matches "${input.card}". The customer's cards are: ${cardsText}. Ask which card they mean.`;
  } else {
    const eligible = all.filter(k => eligibleStatuses.includes(k.status));
    if (eligible.length > 1) {
      result = `WHICH CARD? More than one card can be replaced: ${eligible.map(name).join(' and ')}. Ask which one, then use request_replacement_card again with that card.`;
    } else {
      result = `NOTHING TO REPLACE. None of the customer's cards are blocked, lost, or expired. Their cards are: ${cardsText}. If a card was lost, stolen, or misused, offer to block it first with block_card.`;
    }
  }
}

return { json: { result } };
